/** Widths pre-generated by scripts/generate-screenshots.mjs. */
export const SCREENSHOT_WIDTHS = [800, 1280, 2000] as const

/** `/screenshots/hud.jpg` → `/screenshots/hud-800.avif 800w, …` */
export function screenshotSrcset(src: string, ext: 'avif' | 'webp' | 'jpg'): string {
  const base = src.replace(/\.jpg$/, '')
  return SCREENSHOT_WIDTHS.map(w => `${base}-${w}.${ext} ${w}w`).join(', ')
}

export function screenshotVariant(src: string, width: number, ext: 'avif' | 'webp' | 'jpg'): string {
  return `${src.replace(/\.jpg$/, '')}-${width}.${ext}`
}
